std::unique_ptr<std::map<float, BucketPtr>> partition_map = std::make_unique<std::map<float, BucketPtr>>();
std::vector<BucketPtr> buckets;
float step = 1.0f / (num_buckets * partitions_per_bucket);
for (int i = 0; i < num_buckets; i++) {
    std::vector<float> partition_points;
    for (int j = 0; j < partitions_per_bucket; j++) {
        float point = fmodf(i * partitions_per_bucket + j, num_buckets * partitions_per_bucket) * step;
        partition_points.push_back(point);
    }
    BucketPtr bucket = std::make_shared<Bucket>(std::to_string(i), partition_points);
    buckets.push_back(bucket);
    for (float point : partition_points) {
        (*partition_map)[point] = bucket;
    }
}
buckets_out = buckets;
return partition_map;

